const $=id=>document.getElementById(id);$('connect').onclick=async()=>{const endpoint=$('endpoint').value,key=$('key').value;$('status').textContent='checking…';const r=await fetch('/api/config',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({endpoint,api_key:key})});if(r.ok){$('status').textContent='Connected';$('key').value='';await fetch('/api/health');await fetch('/api/models');await fetch('/api/capabilities')}else $('status').textContent='Connect failed'};$('send').onclick=async()=>{const p=$('prompt').value;$('out').textContent='';const r=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:[{role:'user',content:p}],stream_id:String(Date.now())})});const reader=r.body.getReader(),d=new TextDecoder();let b='';for(;;){const x=await reader.read();if(x.done)break;b+=d.decode(x.value);for(const f of b.split('\n\n').slice(0,-1)){const m=f.match(/event: (\w+)\ndata: (.*)/s);if(m&&m[1]==='delta')$('out').textContent+=JSON.parse(m[2]).text}b=b.split('\n\n').slice(-1)[0]}};